arguments.command:
$srcRoot='C:\Users\MitchellLandreth\Downloads\ignition-ai-toolkit-8-3-downloads'
$destRoot='C:\Users\MitchellLandreth\Git-Local\SHD-Ignition-BOI1\.github\skills'
$tempRoot='C:\Users\MitchellLandreth\.copilot\session-state\266e8d9c-9d05-4e8c-8621-ebbd8d58b5f2\files\skill-install-temp'
if(Test-Path $tempRoot){ Remove-Item -LiteralPath $tempRoot -Recurse -Force }
New-Item -ItemType Directory -Path $tempRoot | Out-Null
$zipPaths = Get-ChildItem -LiteralPath $srcRoot -Recurse -Filter *.zip | Select-Object -ExpandProperty FullName
$installed=@()
foreach($zip in $zipPaths){
  $extractDir = Join-Path $tempRoot ([IO.Path]::GetFileNameWithoutExtension($zip))
  Expand-Archive -LiteralPath $zip -DestinationPath $extractDir -Force
  $skillDirs = Get-ChildItem -LiteralPath $extractDir -Directory
  foreach($skillDir in $skillDirs){
    $dest = Join-Path $destRoot $skillDir.Name
    if(Test-Path $dest){ Remove-Item -LiteralPath $dest -Recurse -Force }
    Copy-Item -LiteralPath $skillDir.FullName -Destination $dest -Recurse -Force
    $installed += $skillDir.Name
  }
}
'Installed skill folders:'
$installed | Sort-Object -Unique

