arguments.command:
$envFile='C:\Users\MitchellLandreth\Git-Local\SHD-Ignition-BOI1\.config\ignition\gateway.env'
$lines = Get-Content -LiteralPath $envFile
$kv = @{}
foreach($line in $lines){
  if($line -match '^\s*export\s+([^=]+)="?(.*?)"?\s*$'){
    $kv[$matches[1]] = $matches[2]
  }
}
$baseUrl = $kv['IGNITION_BASE_URL']
$project = $kv['IGNITION_WEBDEV_PROJECT']
$resource = $kv['IGNITION_WEBDEV_RESOURCE']
$token = $kv['X-Ignition-API-Token']
if(-not $baseUrl -or -not $project -or -not $resource -or -not $token){ throw 'Missing required gateway.env fields' }
$headers = @{ 'X-Ignition-API-Token' = $token; 'Accept'='application/json' }
$route = "$baseUrl/system/webdev/$project/$resource"

$openapiOk = $false
try {
  $openapi = Invoke-RestMethod -Method Get -Uri "$baseUrl/openapi.json" -Headers $headers -TimeoutSec 20
  if($openapi.openapi){ $openapiOk = $true }
} catch {
  $openapiOk = $false
}

$health = Invoke-RestMethod -Method Get -Uri $route -Headers $headers -TimeoutSec 30
$action = 'runtime-profile-v2'
$body = @{ action = $action } | ConvertTo-Json -Compress
$result = Invoke-RestMethod -Method Post -Uri $route -Headers $headers -ContentType 'application/json' -Body $body -TimeoutSec 60
$unknown = Invoke-RestMethod -Method Post -Uri $route -Headers $headers -ContentType 'application/json' -Body (@{ action = 'not-a-real-action' } | ConvertTo-Json -Compress) -TimeoutSec 30

[pscustomobject]@{
  openapiReachable = $openapiOk
  route = $route
  api = $health.api
  version = $health.version
  acceptsArbitraryCode = $health.acceptsArbitraryCode
  availableActionCount = @($health.availableActions).Count
  hasRuntimeProfile = @($health.availableActions) -contains $action
  runtimeProfileAccepted = $result.accepted
  runtimeProfilePassed = $result.passed
  runtimeProfileSideEffects = $result.externalSideEffects
  runtimeProfileTrialState = $result.trialState
  unknownAccepted = $unknown.accepted
  unknownPassed = $unknown.passed
  unknownError = $unknown.error
} | ConvertTo-Json -Depth 8

