arguments.command:
$envFile='C:\Users\MitchellLandreth\Git-Local\SHD-Ignition-BOI1\.config\ignition\gateway.env'
$kv=@{}
Get-Content -LiteralPath $envFile | ForEach-Object { if($_ -match '^\s*export\s+([^=]+)="?(.*?)"?\s*$'){ $kv[$matches[1]]=$matches[2] } }
$headers=@{ 'X-Ignition-API-Token'=$kv['X-Ignition-API-Token']; 'Accept'='application/json' }
$route="$($kv['IGNITION_BASE_URL'])/system/webdev/$($kv['IGNITION_WEBDEV_PROJECT'])/$($kv['IGNITION_WEBDEV_RESOURCE'])"
$actions=@('runtime-profile-v2','perspective-click-counter-v1','vision-client-sessions-v1','expression-tag-fixture-suite-v1')
$results=@()
foreach($a in $actions){
  try{
    $resp = Invoke-RestMethod -Method Post -Uri $route -Headers $headers -ContentType 'application/json' -Body (@{action=$a} | ConvertTo-Json -Compress) -TimeoutSec 60
    $results += [pscustomobject]@{
      action=$a
      accepted=$resp.accepted
      passed=$resp.passed
      error=$resp.error
      externalSideEffects=$resp.externalSideEffects
      trialState=$resp.trialState
      keys=(@($resp.PSObject.Properties.Name) -join ',')
    }
  } catch {
    $results += [pscustomobject]@{ action=$a; accepted=$false; passed=$null; error=$_.Exception.Message; externalSideEffects=$null; trialState=$null; keys=''}
  }
}
$results | ConvertTo-Json -Depth 5

